import{_ as o,o as s,c as a,ah as r}from"./chunks/framework.BMM80GXQ.js";const i="/assets/1.0/images/simple-product/simple.png",p="/assets/1.0/images/simple-product/editProduct.png",n="/assets/1.0/images/simple-product/description.png",l="/assets/1.0/images/simple-product/price.png",c="/assets/1.0/images/simple-product/status.png",d="/assets/1.0/images/simple-product/category.png",u="/assets/1.0/images/simple-product/related.png",e="/assets/1.0/images/simple-product/upsell.png",h="/assets/1.0/images/simple-product/save.png",g="/assets/1.0/images/simple-product/datagrid.png",m="/assets/1.0/images/simple-product/history.png",b="/assets/1.0/images/simple-product/preview.png",_="/assets/1.0/images/simple-product/export.png",w="/assets/1.0/images/simple-product/exportOutput.png",P="/assets/1.0/images/simple-product/final.png",U=JSON.parse('{"title":"Simple Product","description":"","frontmatter":{},"headers":[],"relativePath":"1.0/products/simple.md","filePath":"1.0/products/simple.md","lastUpdated":1775051911000}'),y={name:"1.0/products/simple.md"};function f(S,t,k,q,x,v){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="simple-product" tabindex="-1">Simple Product <a class="header-anchor" href="#simple-product" aria-label="Permalink to &quot;Simple Product&quot;">​</a></h1><p>A simple product is the most basic and common product type. It&#39;s a physical, unique, standalone product without any other variations.</p><p>Simple products offer customizable options within a single SKU.</p><p>This is the step-by-step tutorial on how to add a simple product in <a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a>.</p><h3 id="to-create-simple-product-in-unopim" tabindex="-1">To Create Simple Product in UnoPim <a class="header-anchor" href="#to-create-simple-product-in-unopim" aria-label="Permalink to &quot;To Create Simple Product in UnoPim&quot;">​</a></h3><ol><li>Click on <strong>Catalog &gt;&gt; Products &gt;&gt;</strong> select product type <strong>Simple</strong>,<strong>Family</strong> and enter <strong>SKU</strong>.</li></ol><p><img src="'+i+'" alt="Simple"></p><p>Now <strong>Save the Product</strong>, and you will get redirected to the Edit product page as shown below.</p><h3 id="general-attributes" tabindex="-1">General Attributes <a class="header-anchor" href="#general-attributes" aria-label="Permalink to &quot;General Attributes&quot;">​</a></h3><p>It displays the attributes assigned in the product&#39;s family grouped by attribute group.</p><p>The below given are required attributes present in the &quot;default&quot; family</p><ol><li><p>Enter <strong>SKU</strong> of the product</p></li><li><p>Enter <strong>Name</strong> of the product.</p></li><li><p>Now enter the <strong>URL Key</strong> of the product.</p></li></ol><p><img src="'+p+'" alt="editProduct"></p><h3 id="short-description" tabindex="-1">Short Description <a class="header-anchor" href="#short-description" aria-label="Permalink to &quot;Short Description&quot;">​</a></h3><p>Enter a short description of the features of the product.</p><h3 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h3><p>Mention your product in detail.</p><p><img src="'+n+'" alt="description"></p><h3 id="price" tabindex="-1">Price <a class="header-anchor" href="#price" aria-label="Permalink to &quot;Price&quot;">​</a></h3><p>Insert the price and cost price of the product as shown in the below image</p><p><img src="'+l+'" alt="price"></p><h3 id="technical" tabindex="-1">Technical <a class="header-anchor" href="#technical" aria-label="Permalink to &quot;Technical&quot;">​</a></h3><p>Now Enable the product from the status option as shown below.</p><p><img src="'+c+'" alt="Status"></p><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3><p>You can also assign the product into the root category as shown in the below image.</p><p><img src="'+d+'" alt="Category"></p><h3 id="associations" tabindex="-1">Associations <a class="header-anchor" href="#associations" aria-label="Permalink to &quot;Associations&quot;">​</a></h3><p>Also, you can add the Related Products, Upsell Products, and Cross Sell Products.</p><p><strong>1) Related Products -</strong> Related products are products that are similar to a selected product.</p><p>You can display potential substitutes help to them discover other similar products they might like.</p><p>To add Related Products click on Add in the Related Products section and search the product through the SKU which you want to add as a Related Product as shown in the image below.</p><p><img src="'+u+'" alt="Related"></p><p>Now click on <strong>Add Selected Product</strong> button.</p><p><strong>2) Up-Sell Products -</strong> Upselling is the practice of selling a higher-end version of an item they&#39;re interested in.</p><p>For instance, an electronics retailer pointing out the benefits of a better TV, a faster laptop, or a more durable tablet would be an example of upselling.</p><p>To add Up-Sell Products click on add in the Up-Sell Products section and search the product through the SKU which you want to add as a Up-Sell Product as shown in the image below.</p><p><img src="'+e+'" alt="Upsell"></p><p>Now click on <strong>Add Selected Product</strong> button.</p><p><strong>2) Cross-Sell Products -</strong> Cross-sells are products that you promote, based on the current product. They are typically complementary items.</p><p>For example, if you are selling a laptop, cross-sells might be protective case stickers or a special adapter.</p><p>To add Cross-Sell Products click on add in the Cross-Sell Products section and search the product through SKU which you want to add as a Cross-Sell Product as shown in the image below.</p><p><img src="'+e+'" alt="Upsell"></p><p>Now click on <strong>Add Selected Product</strong> button.</p><p>You can also add as many products as per your requirements.</p><p>At last, <strong>Save the Product</strong>.</p><p><img src="'+h+'" alt="Save"></p><p>Now the product is created successfully and it will be visible in <strong>Products Data Grid</strong> as shown in the below image.</p><p><img src="'+g+'" alt="Datagrid"></p><p>Additionally, you can view the product history by navigating to <strong>Catalog &gt;&gt; Products &gt;&gt; Edit Product</strong> and clicking on <strong>History</strong> as shown below.</p><p><img src="'+m+'" alt="History"></p><p>Afterwards, in the <strong>Actions</strong> you can view the product history as shown below.</p><p><img src="'+b+'" alt="Preview"></p><p>Additionally, you can quickly export your data in CSV, XLS, or XLSX formats.</p><p><img src="'+_+'" alt="Export"></p><p>Now, click on <strong>Quick Export button</strong> to export the data.</p><p><img src="'+w+'" alt="Export Output"></p><p><strong>Note-</strong> Attributes that support values per channel will display a channel badge, while attributes that support values per locale will display a locale badge. If an attribute supports both values per channel and values per locale, it will display both badges.</p><p><img src="'+P+'" alt="Export Output"></p>',59)])])}const C=o(y,[["render",f]]);export{U as __pageData,C as default};
